import * as React from 'react';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import LockOpenOutlinedIcon from '@mui/icons-material/LockOpenOutlined';
import Box from '@mui/material/Box';
import IconButton from '@mui/material/IconButton';
import { RichTreeView } from '@mui/x-tree-view/RichTreeView';
import { TreeItem, TreeItemContent, TreeItemProps } from '@mui/x-tree-view/TreeItem';
import {
  useTreeItem,
  UseTreeItemContentSlotOwnProps,
  UseTreeItemStatus,
} from '@mui/x-tree-view/useTreeItem';
import { MUI_X_PRODUCTS } from '../../datasets/disabledAndEditableProducts';

interface CustomContentProps extends UseTreeItemContentSlotOwnProps {
  children: React.ReactNode;
  toggleItemDisabled: () => void;
  disabled: boolean;
  status: UseTreeItemStatus;
}

function CustomContent({
  children,
  toggleItemDisabled,
  disabled,
  status,
  ...props
}: CustomContentProps) {
  return (
    <TreeItemContent {...props} status={status}>
      {children}

      <IconButton
        size="small"
        onClick={(event) => {
          event?.stopPropagation();
          toggleItemDisabled();
        }}
      >
        {disabled ? (
          <LockOutlinedIcon fontSize="small" />
        ) : (
          <LockOpenOutlinedIcon fontSize="small" />
        )}
      </IconButton>
    </TreeItemContent>
  );
}

const CustomTreeItem = React.forwardRef(function CustomTreeItem(
  props: TreeItemProps,
  ref: React.Ref<HTMLLIElement>,
) {
  const { publicAPI, status } = useTreeItem(props);

  const toggleItemDisabled = () =>
    publicAPI.setIsItemDisabled({
      itemId: props.itemId,
    });

  return (
    <TreeItem
      {...props}
      ref={ref}
      slots={{
        content: CustomContent,
      }}
      slotProps={{
        content: {
          toggleItemDisabled,
          disabled: status.disabled,
          status,
        } as CustomContentProps,
      }}
    />
  );
});

export default function DisableTreeItemPublicAPI() {
  return (
    <Box sx={{ minHeight: 200, minWidth: 350 }}>
      <RichTreeView
        defaultExpandedItems={['pickers']}
        items={MUI_X_PRODUCTS}
        slots={{ item: CustomTreeItem }}
      />
    </Box>
  );
}

